check(UserPreferences::partnerRead($db,9,1,2)===42,'Scoped DM cursor');$db->exec('UPDATE user_settings SET read_receipts=0 WHERE user_id=1');check(UserPreferences::partnerRead($db,9,1,2)===null,'Viewer receipt opt-out');$db->exec('UPDATE user_settings SET read_receipts=1 WHERE user_id=1');$db->exec('UPDATE user_settings SET read_receipts=0 WHERE user_id=2');check(UserPreferences::partnerRead($db,9,1,2)===null,'Partner receipt opt-out');
